function parse(s){const [y,m,d]=s.split('-').map(Number);return new Date(y,m-1,d,12)}
function fmt(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function add(s,n){const x=parse(s);x.setDate(x.getDate()+n);return fmt(x)}
function dayDiff(a,b){return Math.round((parse(a)-parse(b))/DAY)}
function clampDate(s){return s<START?START:s>END?END:s}
